add_action( 'woocommerce_after_checkout_validation', 'perfectpixel_deny_checkout_by_weight', 10, 2 );

function perfectpixel_deny_checkout_by_weight( $data, $errors ) {
	$max    = (float) '{{max_cart_weight}}';
	$weight = WC()->cart ? (float) WC()->cart->get_cart_contents_weight() : 0;
	if ( $max <= 0 || $weight <= $max ) {
		return;
	}
	$unit = get_option( 'woocommerce_weight_unit' );
	$errors->add(
		'perfectpixel_max_weight',
		sprintf(
			esc_html( '{{max_weight_message}}' ),
			esc_html( wc_format_localized_decimal( wc_format_decimal( $weight, 2 ) ) . ' ' . $unit ),
			esc_html( wc_format_localized_decimal( wc_format_decimal( $max, 2 ) ) . ' ' . $unit )
		)
	);
}
